import {describe, it, expect, vi} from 'vitest';
import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import {ErrorCodes} from '../../types/session.js';
import type {ChatSession} from '../../types/session.js';
import type {SessionStore} from '../../types/sessionStore.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';

describe('createMessageHandler history opt-in', () => {
  const orchestrator = {} as ChatOrchestrator;
  const session = {sessionId: 's1', userId: 'u1'} as ChatSession;
  const store = {
    listFor: vi.fn().mockResolvedValue([]),
  } as unknown as SessionStore;

  it('answers list_sessions with UNSUPPORTED when history is not enabled (default)', async () => {
    const handler = createMessageHandler(orchestrator, store);
    const ws = {
      send: vi.fn(),
      readyState: WebSocket.OPEN,
    } as unknown as WebSocket;

    await handler(ws, session, {type: 'list_sessions'});

    expect(ws.send).toHaveBeenCalledWith(
      JSON.stringify({
        type: 'error',
        code: 'UNSUPPORTED',
        message: 'History is not enabled',
      })
    );
    expect(store.listFor).not.toHaveBeenCalled();
  });
});

